{
  "root": "main_stack",
  "state": {
    "weatherMetrics": [
      {
        "feature": "Daily Temp Range",
        "bangkok": "22°C - 32°C (72°F - 90°F)",
        "hanoi": "14°C - 20°C (57°F - 68°F)"
      },
      {
        "feature": "Humidity",
        "bangkok": "65-70% (Comfortable for tropics)",
        "hanoi": "75-82% (Damp/Misty)"
      },
      {
        "feature": "Rain Probability",
        "bangkok": "Very Low (<2 days/month)",
        "hanoi": "Moderate (5-7 days, mostly drizzle)"
      },
      {
        "feature": "Sky Conditions",
        "bangkok": "Mostly Clear / Sunny",
        "hanoi": "Often Overcast / Gray"
      },
      {
        "feature": "Walking Comfort",
        "bangkok": "Low (Heat fatigue likely)",
        "hanoi": "High (Cool, sweat-free)"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "title_january_climate",
        "intro_para_1",
        "intro_para_2",
        "heading_metrics",
        "weather_table",
        "heading_verdict",
        "hanoi_verdict_heading",
        "hanoi_verdict_text",
        "bangkok_verdict_heading",
        "bangkok_verdict_text",
        "heading_sources",
        "sources_stack"
      ]
    },
    "title_january_climate": {
      "type": "Text",
      "props": {
        "text": "January Climate Snapshot",
        "variant": "h1"
      },
      "children": []
    },
    "intro_para_1": {
      "type": "Text",
      "props": {
        "text": "January is widely considered the peak travel season for both cities, but for very different reasons. Bangkok experiences its \"cool\" season, which is dry and sunny but still hot by global standards. Hanoi experiences a true winter, which is significantly cooler and often overcast with mist. For a walking tour, Hanoi offers much more comfortable temperatures, while Bangkok guarantees brighter photography conditions at the cost of heat exhaustion risks.",
        "variant": "body"
      },
      "children": []
    },
    "intro_para_2": {
      "type": "Text",
      "props": {
        "text": "The following comparison relies on historical climate averages collected over the last 30 years. January weather patterns in Southeast Asia are generally stable, but short-term fluctuations (such as cold snaps in Hanoi or heatwaves in Bangkok) can occur. \"Rainfall probability\" here refers to the likelihood of measurable precipitation days, though intensity varies (Bangkok rain is rare/short; Hanoi rain is often a persistent light drizzle).",
        "variant": "body"
      },
      "children": []
    },
    "heading_metrics": {
      "type": "Text",
      "props": {
        "text": "Bangkok vs Hanoi Weather Metrics",
        "variant": "h2"
      },
      "children": []
    },
    "weather_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "bangkok",
            "label": "Bangkok (Thailand)"
          },
          {
            "key": "hanoi",
            "label": "Hanoi (Vietnam)"
          }
        ],
        "statePath": "/weatherMetrics",
        "domain": "weather",
        "preferredPresentation": "cards",
        "sourceFormat": "markdown",
        "sourceText": "| Feature | Bangkok (Thailand) | Hanoi (Vietnam) |\n| :--- | :--- | :--- |\n| **Daily Temp Range** | 22°C - 32°C (72°F - 90°F) | 14°C - 20°C (57°F - 68°F) |\n| **Humidity** | 65-70% (Comfortable for tropics) | 75-82% (Damp/Misty) |\n| **Rain Probability** | Very Low (<2 days/month) | Moderate (5-7 days, mostly drizzle) |\n| **Sky Conditions** | Mostly Clear / Sunny | Often Overcast / Gray |\n| **Walking Comfort** | Low (Heat fatigue likely) | High (Cool, sweat-free) |"
      },
      "children": []
    },
    "heading_verdict": {
      "type": "Text",
      "props": {
        "text": "Walking Tour Verdict",
        "variant": "h2"
      },
      "children": []
    },
    "hanoi_verdict_heading": {
      "type": "Text",
      "props": {
        "text": "Choose Hanoi if:",
        "variant": "h3"
      },
      "children": []
    },
    "hanoi_verdict_text": {
      "type": "Text",
      "props": {
        "text": "You prioritize physical comfort and want to explore the Old Quarter for hours without sweating. The cooler temperatures (similar to a mild European autumn) make it ideal for long treks, though photographs may look gloomy due to the common \"milk fog.\"",
        "variant": "body"
      },
      "children": []
    },
    "bangkok_verdict_heading": {
      "type": "Text",
      "props": {
        "text": "Choose Bangkok if:",
        "variant": "h3"
      },
      "children": []
    },
    "bangkok_verdict_text": {
      "type": "Text",
      "props": {
        "text": "You want vibrant blue skies for photography and don't mind the heat. Walking tours here are best done early morning (6:00 AM - 10:00 AM) or late evening. Mid-day walking is strenuous due to the blazing sun.",
        "variant": "body"
      },
      "children": []
    },
    "heading_sources": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_wmo",
        "button_tourismthailand",
        "button_vietnamtourism"
      ]
    },
    "button_wmo": {
      "type": "Button",
      "props": {
        "label": "World Weather Information Service",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://worldweather.wmo.int/"
          }
        }
      },
      "children": []
    },
    "button_tourismthailand": {
      "type": "Button",
      "props": {
        "label": "Tourism Authority of Thailand",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tourismthailand.org/"
          }
        }
      },
      "children": []
    },
    "button_vietnamtourism": {
      "type": "Button",
      "props": {
        "label": "Vietnam National Authority of Tourism",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://vietnamtourism.gov.vn/"
          }
        }
      },
      "children": []
    }
  }
}
